example.before:
// DRY violation - repeated logic
function processUserA(user: User): Result {
  if (user.isActive && user.hasPermission) {
    return { success: true, data: `User ${user.name} is valid` };
  } else {
    return { success: false, error: "Invalid user" };
  }
}

function processUserB(user: User): Result {
  if (user.isActive && user.hasPermission) {
    return { success: true, data: `User ${user.name} is valid` };
  } else {
    return { success: false, error: "Invalid user" };
  }
}

example.after:
// DRY - extracted common logic
function validateUser(user: User): Result {
  if (user.isActive && user.hasPermission) {
    return { success: true, data: `User ${user.name} is valid` };
  } else {
    return { success: false, error: "Invalid user" };
  }
}

function processUserA(user: User): Result {
  return validateUser(user);
}

function processUserB(user: User): Result {
  return validateUser(user);
}

example.before:
// Violates Open/Closed - requires modification for new types
function processData(data: Data): string {
  switch (data.type) {
    case "text":
      return `Text: ${data.value}`;
    case "number":
      return `Number: ${data.value}`;
    // Must modify here for new types
    default:
      return "Unknown";
  }
}

example.after:
// Open/Closed - extensible without modification
interface Processable {
  process(): string;
}

class TextData implements Processable {
  constructor(private value: string) {}
  process(): string {
    return `Text: ${this.value}`;
  }
}

class NumberData implements Processable {
  constructor(private value: number) {}
  process(): string {
    return `Number: ${this.value}`;
  }
}

function processData(data: Processable): string {
  return data.process();
}

example.before:
// Type-unsafe state representation
type State = {
  status: "loading" | "success" | "error";
  data?: string;
  error?: string;
};

function handleState(state: State) {
  if (state.status === "success") {
    // TypeScript doesn't know data is defined
    console.log(state.data?.toUpperCase());
  }
}

example.after:
// Type-safe discriminated union
type State =
  | { status: "loading" }
  | { status: "success"; data: string }
  | { status: "error"; error: string };

function handleState(state: State) {
  if (state.status === "success") {
    // TypeScript knows data is defined
    console.log(state.data.toUpperCase());
  }
}

example.before:
// Imperative loop
function filterAndMap(numbers: number[]): number[] {
  const result: number[] = [];
  for (const n of numbers) {
    if (n > 0) {
      result.push(n * 2);
    }
  }
  return result;
}

example.after:
// Functional methods - more idiomatic
function filterAndMap(numbers: number[]): number[] {
  return numbers
    .filter(n => n > 0)
    .map(n => n * 2);
}

example.before:
// Unsafe type assertion
function processValue(value: unknown): string {
  return (value as string).toUpperCase();
}

example.after:
// Type-safe type guard
function isString(value: unknown): value is string {
  return typeof value === "string";
}

function processValue(value: unknown): string {
  if (isString(value)) {
    return value.toUpperCase();
  }
  throw new Error("Value is not a string");
}

example.before:
// Hard dependency - hard to test
class UserService {
  async getUser(id: string): Promise {
    const response = await fetch(`/api/users/${id}`);
    return response.json();
  }
}

example.after:
// Dependency injection - testable
interface HttpClient {
  get(url: string): Promise;
}

class UserService {
  constructor(private http: HttpClient) {}

  async getUser(id: string): Promise {
    const response = await this.http.get(`/api/users/${id}`);
    return response as User;
  }
}
